package org.sleepwell.app;
import android.view.*;import android.widget.Switch;import org.junit.Test;import java.io.File;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Shared owned-input harness, real private settings; no capture, inference, service or outputs. */
public final class SoundInclusionFlowTest {
 void selected(SoundSensitivityFlowTest h,String category,boolean expected)throws Exception{h.await(()->{boolean[] yes={false};h.i.runOnMainSync(()->{View control=h.find(h.activity.getWindow().getDecorView(),"Include "+SoundSensitivity.label(category));yes[0]=control instanceof Switch&&((Switch)control).isChecked()==expected;});return yes[0];});}
 void open(SoundSensitivityFlowTest h)throws Exception{h.click("Choose detected categories");h.await(()->h.shown("Include Snoring"));}
 void capture(SoundSensitivityFlowTest h,String name)throws Exception{h.step="capture inclusion "+name;h.ready();h.frame(h.activity.getWindow().getDecorView());assertTrue(h.d.takeScreenshot(new File(h.folder(),"sound-inclusion-"+name+".png")));}
 @Test public void everyCategoryCanBeSavedRecreatedAndReopenedWithoutChangingActivePolicy()throws Exception{SoundSensitivityFlowTest h=new SoundSensitivityFlowTest();h.fixture(f->{h.launch();SoundSensitivity admitted=SoundSensitivitySettings.snapshot(h.c);open(h);capture(h,"default");h.click("Include Speech");assertEquals(SoundSensitivity.DEFAULT,f.read().policy);h.click("Back");h.await(()->h.shown("Sound sensitivity"));h.click("Back");h.await(h.activity::isDestroyed);assertTrue(h.activity.awaitWorkers(8000));h.launch();open(h);selected(h,"speech",true);capture(h,"cancelled");for(String category:SoundSensitivity.SELECTABLE){h.click("Include "+SoundSensitivity.label(category));selected(h,category,false);h.recreate();selected(h,category,false);assertEquals(6,admitted.selectedCount());if(category.equals("snoring"))capture(h,"draft-recreated");h.click("Save sensitivity");h.await(()->h.shown("Saved for the next night."));assertFalse(f.read().policy.includes(category));h.reopen();open(h);selected(h,category,false);assertFalse(f.read().policy.allIncluded());if(category.equals("noise"))capture(h,"reopened");h.click("Include "+SoundSensitivity.label(category));selected(h,category,true);h.click("Save sensitivity");h.await(()->h.shown("Saved for the next night."));assertEquals(SoundSensitivity.DEFAULT,f.read().policy);}assertEquals(12,f.saves.get());capture(h,"restored");});}
 @Test public void lastEnabledCategoryCannotBeDisabledAndHeldSaveRetainsSelection()throws Exception{SoundSensitivityFlowTest h=new SoundSensitivityFlowTest();h.fixture(f->{h.launch();open(h);for(String category:SoundSensitivity.SELECTABLE)if(!category.equals("speech"))h.click("Include "+SoundSensitivity.label(category));h.click("Include Speech");h.await(()->h.shown("Keep at least one category on."));selected(h,"speech",true);capture(h,"last-required");h.recreate();h.await(()->h.shown("Keep at least one category on."));selected(h,"speech",true);f.block=new CountDownLatch(1);h.click("Save sensitivity");assertTrue(f.entered.await(5,TimeUnit.SECONDS));h.recreate();h.await(()->h.shown("Saving…"));for(String category:SoundSensitivity.SELECTABLE)h.i.runOnMainSync(()->assertFalse(h.find(h.activity.getWindow().getDecorView(),"Include "+SoundSensitivity.label(category)).isEnabled()));capture(h,"saving-recreated");f.block.countDown();h.await(()->h.shown("Saved for the next night."));assertEquals(1,f.saves.get());assertEquals(1,f.read().policy.selectedCount());assertTrue(f.read().policy.includes("speech"));h.reopen();open(h);selected(h,"speech",true);selected(h,"snoring",false);capture(h,"speech-only");});}
 @Test public void unavailablePrivateStoreShowsAnErrorAndOnlyExplicitSaveCanRecover()throws Exception{SoundSensitivityFlowTest h=new SoundSensitivityFlowTest();h.fixture(f->{java.util.concurrent.atomic.AtomicBoolean unavailable=new java.util.concurrent.atomic.AtomicBoolean(true);h.i.runOnMainSync(()->SoundSensitivitySettings.factory=context->{if(unavailable.get())throw new IllegalStateException("Unavailable settings fixture");return f;});h.launch();h.await(()->h.shown("Saved settings could not be read. Review and save to enable analysis."));assertFalse(SoundSensitivitySettings.snapshot(h.c).available());assertTrue(f.prefs.getAll().isEmpty());unavailable.set(false);assertTrue(f.prefs.getAll().isEmpty());h.click("Save sensitivity");h.await(()->h.shown("Saved for the next night."));assertEquals(1,f.saves.get());assertTrue(SoundSensitivitySettings.snapshot(h.c).available());h.recreate();h.await(()->h.shown("Saved for the next night."));assertEquals(SoundSensitivity.DEFAULT,f.read().policy);});}

}
